package glitch

import data.glitch_lib

# Set of keywords indicating static credential fields based on CWE-798
credential_keywords := {"password", "secret", "token", "key", "credential", "username", "access_key", "secret_key", "api_key", "auth", "client_secret", "admin_user", "default_login", "initial_password", "builtin_account", "connection_string", "endpoint_credentials", "service_token", "remote_key", "private_key", "certificate", "encryption_key", "signed_secret"}

# Helper to check if a string contains any credential keyword (case-insensitive)
contains_credential_keyword(str) {
    some kw
    kw := credential_keywords[_]
    regex.match(sprintf("(?i).*%s.*", [kw]), str)
}

# Check if an attribute name matches credential keywords
is_credential_attribute(attr_name) {
    contains_credential_keyword(attr_name)
}

# Check if a value is a static string (not a variable reference or function call)
is_static_string(value) {
    value.ir_type == "String"
}

# Check if a value is a static array of strings (e.g., for keys)
is_static_array_of_strings(value) {
    value.ir_type == "Array"
    some elem
    elem := value.value[_]
    elem.ir_type == "String"
}

# Check if a node contains a variable reference (indicating it's not static)
has_variable_reference(node) {
    walk(node, [_, n])
    n.ir_type == "VariableReference"
}

# Check if a node contains a function call (e.g., env() or secret manager lookup)
has_function_call(node) {
    walk(node, [_, n])
    n.ir_type == "FunctionCall"
}

# Check if a value is truly static (no variables or function calls)
is_truly_static(value) {
    is_static_string(value)
    not has_variable_reference(value)
    not has_function_call(value)
} else {
    is_static_array_of_strings(value)
    not has_variable_reference(value)
    not has_function_call(value)
}

# Main rule to detect hard-coded credentials in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Get all attributes from the atomic unit
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name indicates a credential
    is_credential_attribute(attr.name)

    # Check if the value is a static string or array of strings
    is_truly_static(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid using static credentials in IaC scripts. (CWE-798)"
    }
}

# Additional rule to detect hard-coded credentials in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    variable := variables[_]

    # Check if variable name indicates a credential
    is_credential_attribute(variable.name)

    # Check if the value is a static string or array of strings
    is_truly_static(variable.value)

    result := {
        "type": "sec_hard_secr",
        "element": variable,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid using static credentials in IaC scripts. (CWE-798)"
    }
}

